from functools import lru_cache

MOD = 1000000007

def solution(n_input):
    lines = n_input.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    # Find missing values and positions with -1
    present = set()
    missing_values = []
    ones_positions = []

    for i, x in enumerate(a):
        if x == -1:
            ones_positions.append(i + 1)  # 1-indexed position
        else:
            present.add(x)

    for v in range(1, n + 1):
        if v not in present:
            missing_values.append(v)

    # Use inclusion-exclusion principle
    # We want to count ways to match missing_values to ones_positions
    # such that value i never gets position i

    num_positions = len(ones_positions)
    num_values = len(missing_values)

    # These should be equal
    if num_positions != num_values:
        return '0\n'
    if num_positions == 0:
        return '1\n'

    # Count how many positions i have the forbidden property: ones_positions[i] == missing_values[i]
    # After sorting corresponding pairs
    forbidden_count = 0
    for i in range(num_positions):
        if ones_positions[i] == missing_values[i]:
            forbidden_count += 1

    # dp[k] = number of derangements of k elements
    # derangements(0) = 1, derangements(1) = 0, derangements(n) = (n-1)*(derangements(n-1) + derangements(n-2))

    @lru_cache(None)
    def derangements(n):
        if n == 0:
            return 1
        if n == 1:
            return 0
        return (n - 1) * (derangements(n - 1) + derangements(n - 2)) % MOD

    result = 0

    # Inclusion-exclusion: sum over choosing i forbidden pairs to ALLOW (C(f, i) * derangements(f-i))
    # If even number of forbidden pairs allowed, add; if odd, subtract

    from math import comb

    for i in range(forbidden_count + 1):
        ways = comb(forbidden_count, i)
        d = derangements(forbidden_count - i)
        term = ways * d

        if i % 2 == 0:
            result = (result + term) % MOD
        else:
            result = (result - term + MOD) % MOD

    return f'{result}\n'

