def solution(s):
    lines = s.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    if n == 1 and a[0] == 1:
        return "YES"

    # Use DFS with memoization to find if we can reach 1
    # State: tuple of available numbers
    memo = {}

    def dfs(numbers):
        if len(numbers) == 1:
            return numbers[0] == 1

        key = tuple(sorted(numbers))
        if key in memo:
            return False
        memo[key] = False

        # Try all pairs
        for i in range(len(numbers)):
            for j in range(i + 1, len(numbers)):
                x = numbers[i]
                y = numbers[j]
                new_val = f(x + y, k)

                if new_val == 1:
                    # Found solution path - we'll track operations separately
                    return True
                else:
                    remaining = list(numbers)
                    remaining.pop(j + i)
                    remaining[i] = new_val
                    remaining.sort()

                    if dfs(remaining):
                        return True

        return False

    if dfs(a):
        # Now we need to reconstruct the actual solution
        # Do it with explicit tracking
        ops = []

        def dfs_with_ops(numbers_list, used_mask, path_ops):
            if len(numbers_list) == 1:
                return numbers_list[0] == 1, path_ops

            key = tuple(sorted(numbers_list))
            if key in memo:
                return False, []

            for i in range(len(numbers_list)):
                for j in range(i + 1, len(numbers_list)):
                    x = numbers_list[i]
                    y = numbers_list[j]
                    new_val = f(x + y, k)

                    if new_val == 1:
                        if i == j - 1:
                            used_mask |= (1 << i)
                            used_mask |= (1 << j)
                            ops = path_ops + [(x, y)]
                            return True, ops
                        remaining = list(numbers_list)
                        remaining.pop(j + i)
                        remaining[i] = new_val
                        remaining.sort()

                        ans, path = dfs_with_ops(remaining, used_mask, path_ops + [(x, y)])
                        if ans:
                            return True, path + [(x, y)]

                    remaining = list(numbers_list)
                    remaining.pop(j + i)
                    remaining[i] = new_val
                    remaining.sort()

                    ans, path = dfs_with_ops(remaining, used_mask, path_ops)
                    if ans:
                        return True, path + [(x, y)]

            return False, []

        success, path = dfs_with_ops(a, 0, [])
        if success:
            result_lines = ["YES"]
            for x, y in path:
                result_lines.append(f"{x} {y}")
            return "\n".join(result_lines)
        else:
            return "NO"
    else:
        return "NO"

