    lines = s.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    sum_a = sum(a)

    # If all boxes are empty
    if sum_a == 0:
        return "0"

    # If only 1 box exists
    if n == 1:
        if sum_a == 1:
            return "-1"
        return "0"  # sum > 1, so at least k = sum_a works

    # Find all divisors of sum_a
    divisors = set()
    for i in range(2, int(sum_a**0.5) + 1):
        if sum_a % i == 0:
            divisors.add(i)
            if i != sum_a // i:
                divisors.add(sum_a // i)
    divisors.add(sum_a)

    min_cost = float('inf')

    for k in divisors:
        if k <= 1:
            continue

        cost = 0
        cumulative = 0
        # Process n-1 boundaries (between positions 0-1, 1-2, ..., n-2-(n-1))
        for i in range(n - 1):
            cumulative += a[i]
            ir = cumulative % k
            # At each boundary, either push ir chocolates right or (k-ir) left
            cost += min(ir, k - ir)

        min_cost = min(min_cost, cost)

    return str(min_cost)

