    lines = input_str.strip().split('\n')
    if not lines or not lines[0].strip():
        return "-1"

    N = int(lines[0])

    # Parse costs - costs[i][j] = cost for city i to build rail to city j
    costs = []
    for i in range(N):
        row = list(map(int, lines[i+1].split()))
        full_row = [0] * N
        idx = 0
        for j in range(N):
            if j == i:
                continue
            full_row[j] = row[idx]
            idx += 1
        costs.append(full_row)

    # Build preference list: pref_list[i][k] = the k-th best city for city i
    pref_list = []
    for i in range(N):
        pairs = []
        for j in range(N):
            if i != j:
                pairs.append((costs[i][j], j))
        pairs.sort()
        pref_list.append([p[1] for p in pairs])

    # Build preference ranks: pref_rank[i][j] = rank of city j in city i's preferences (1 = best)
    pref_rank = [[0] * N for _ in range(N)]
    for i in range(N):
        pairs = []
        for j in range(N):
            if i != j:
                pairs.append((costs[i][j], j))
        pairs.sort()
        for rank, (_, c) in enumerate(pairs, 1):
            pref_rank[i][c] = rank

    match = [-1] * N
    q = list(range(N))

    max_rounds = 20 * N * N if N else N * N

    for _ in range(max_rounds):
        if not q:
            break

        match = match[:]
        q = q[:]

        for p in q:
            if match[p] != -1:
                continue

            for c in pref_list[p]:
                if match[c] == -1:
                    match[p] = c
                    match[c] = p
                    q.remove(p)
                    break
                else:
                    current_partner = match[c]
                    if pref_rank[c][p] < pref_rank[c][current_partner]:
                        match[p] = c
                        match[c] = p

                        if current_partner != -1:
                            q.append(current_partner)

                        q.remove(p)
                        break

        # Check if stable
        stable = True
        for i in range(N):
            if match[i] == -1:
                for j in range(N):
                    if match[j] == -1 and i != j:
                        continue
                continue
            for j in range(i + 1, N):
                if match[i] == j:
                    continue
                if match[j] == -1:
                    continue
                if match[j] != i:
                    if pref_rank[i][j] < pref_rank[i][match[i]] and pref_rank[j][i] < pref_rank[j][match[j]]:
                        stable = False
                        break

        if stable and -1 not in match:
            return "\n".join(str(match[i] + 1) for i in range(N))

    return "-1"

