        for l, r in offers:
            # Check length requirement
            if r - l + 1 >= x:
                # Check overlap with previously selected offers
                overlap = False
                for (al, ar) in selected:
                    # Two intervals [l, r] and [al, ar] overlap if l <= ar and al <= r
                    if l <= ar and al <= r:
                        overlap = True
                        break
                if not overlap:
                    selected.append((l, r))
                    # Mark all days in this interval as occupied
                    for day in range(l, r + 1):
                        current_occupied.add(day)

        results.append(str(len(current_occupied)))

    return '\n'.join(results) + '\n'

