MOD = 10**9 + 7

def matrix_mult(A, B):
    C = [[0, 0, 0] for _ in range(3)]
    for i in range(3):
        for j in range(3):
            for k in range(3):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def matrix_pow(A, p):
    if p == 0:
        return [[1, 0, 0], [0, 1, 0], [0, 0, 1]]
    result = [[1, 0, 0], [0, 1, 0], [0, 0, 1]]
    base = A
    while p > 0:
        if p % 2 == 1:
            result = matrix_mult(result, base)
        base = matrix_mult(base, base)
        p //= 2
    return result

