        return "0\n"

    INF = float('inf')
    cell_costs = [[0] * M for _ in range(N)]

    # Precompute transformer positions in the grid and accumulate costs
    max_time = N + M - 1

    for x, y, d, t, e in transformers:
        max_offset = max_time - t
        if max_offset < 0:
            continue

        for offset in range(max_offset + 1):
            mod = offset % 4
            if mod == 0:
                r1, c1 = x, y
            elif mod == 1:
                r1, c1 = x + d, y - d
            elif mod == 2:
                r1, c1 = x + d, y
            else:  # mod == 3
                r1, c1 = x, y + d

            if 0 <= r1 < N and 0 <= c1 < M:
                cell_costs[r1][c1] += e

    # Dynamic programming to find minimum cost path
    dp = [[INF] * M for _ in range(N)]
    dp[0][0] = cell_costs[0][0]

    for r in range(N):
        for c in range(M):
            if r == 0 and c == 0:
                continue

            min_prev = INF
