                    if min(x1, x2) <= px <= max(x1, x2):
                        on_boundary = True
                        break
        return crosses % 2 == 1 and not on_boundary

    def is_safe_for_T(T: float) -> bool:
        """Check if pedestrian can cross in time T with optimal waiting strategy"""
        # With total time T, pedestrian waits W = T - w/u, then walks at speed u
        W = T - w / u
        if W < 0:
            return False

        # During crossing, pedestrian is at height y at time t = W + y/u
        # At this time, the bus has moved left by v * t
        # So we need (v * t, y) to NOT be strictly inside polygon

        # Check at critical heights where polygon edges might intersect x=0
        # Also check dense grid for safety

        for i in range(10001):
            y = i * w / 10000.0
            t = W + y / u
            bus_x = v * t
            if bus_x == 0:  # Also check original polygon at (0, y)
                if in_polygon_strict(0, y):
                    return False
            if in_polygon_strict(bus_x, y):
                return False
        return True

    # Binary search for minimum T
    low, high = w / u, w / u + 10000.0

    for _ in range(100):
        mid = (low + high) / 2
        if is_safe_for_T(mid):
            high = mid
        else:
            low = mid

    return f"{high:.10f}\n"

from functools import lru_cache

def solution(input_str):
    n, k, m = map(int, input_str.split())
    MOD = 10**9 + 7

    @lru_cache(maxsize=None)
    def dfs(current_pos, count, visited_mask):
        if count == k:
            return 1

        total = 0
        # Can move to any planet y where 1 <= y <= current_pos + m and y not visited
        for next_pos in range(1, min(n + 1, current_pos + m + 1)):
            if not (visited_mask & (1 << (next_pos - 1))):
                total = (total + dfs(next_pos, count + 1, visited_mask | (1 << (next_pos - 1)))) % MOD

        return total

    # Sum over all possible starting positions
    ans = 0
    for start in range(1, n + 1):
        ans = (ans + dfs(start, 1, 1 << (start - 1))) % MOD

    # Clear the cache since this function may be called multiple times
    dfs.cache_clear()

    return str(ans)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    matrix = []
    for i in range(1, n + 1):
        matrix.append(list(map(int, lines[i].split())))

    # Count factors of 2 and 5 for each cell
    cnt2 = [[0] * n for _ in range(n)]
    cnt5 = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            num = matrix[i][j]
            temp = num
            while temp > 0 and temp % 2 == 0:
                cnt2[i][j] += 1
                temp //= 2
            temp = num
            while temp > 0 and temp % 5 == 0:
                cnt5[i][j] += 1
                temp //= 5

    # dp[i][j] = list of (c2, c5) pairs, Pareto-optimal for paths from (i,j) to (n-1,n-1)
    dp = [[[] for _ in range(n)] for _ in range(n)]

    # Base case: bottom-right cell
    dp[n-1][n-1] = [(cnt2[n-1][n-1], cnt5[n-1][n-1])]

    # Fill DP from bottom-right to top-left
    for i in range(n-1, -1, -1):
        for j in range(n-1, -1, -1):
            if i == n - 1 and j == n - 1:
                continue

            c2_here, c5_here = cnt2[i][j], cnt5[i][j]
            options = set()

            if matrix[i][j] == 0:
                dp[i][j] = [(0, 0)]
                continue

            # Try going Down
            if i < n - 1:
                for c2_down, c5_down in dp[i+1][j]:
                    options.add((c2_down + c2_here, c5_down + c5_here))

            # Try going Right
            if j < n - 1:
                for c2_right, c5_right in dp[i][j+1]:
                    options.add((c2_right + c2_here, c5_right + c5_here))

            # Keep only Pareto-optimal: if exists (a,b) and (c,d) with a<=c and b<=d, remove (c,d)
            pareto = []
            for opt in options:
                dom = False
                for po in pareto:
                    if po[0] <= opt[0] and po[1] <= opt[1] and po != opt:
                        dom = True
                        break
                if not dom:
                    # Remove dominated opts from pareto
                    new_pareto = []
                    for po in pareto:
                        new_pareto.append(po)
                        if po[0] > opt[0] and po[1] > opt[1]:
                            new_pareto[-1] = opt
                    pareto = new_pareto
                else:
                    # Check if opt dominates any in pareto
                    for idx, po in enumerate(pareto):
                        if po[0] > opt[0] and po[1] > opt[1]:
                            pareto[idx] = opt
                            break
                    else:
                        pareto.append(opt)

            dp[i][j] = pareto

    # Backtrack to reconstruct path
    path = []
    i, j = 0, 0

    while True:
        if i < n - 1 and j < n - 1:
            down_dps = dp[i+1][j]
            right_dps = dp[i][j+1]

            # Choose direction that gives min trailing zeros
            min_zeros_down = min((c2 + cnt2[i][j], c5 + cnt5[i][j]) for c2, c5 in down_dps)
            min_zeros_right = min((c2 + cnt2[i][j], c5 + cnt5[i][j]) for c2, c5 in right_dps)

            if min(min(c2, c5) for c2, c5 in down_dps) <= min(min(c2, c5) for c2, c5 in right_dps):
                path.append('D')
                i += 1
            else:
                path.append('R')
                j += 1
        elif i < n - 1:
            path.append('D')
            i += 1
        else:
            path.append('R')
            j += 1

    # Reverse path since we built it backwards
    path.reverse()
    min_result = min(min(c2, c5) for c2, c5 in dp[0][0])

    return f"{min_result}\n{\"".join(path)}"

def sum_floor(n):
    total = 0
    l = 1
    while l <= n:
        val = n // l
        if val == 0:
            r = n
        else:
            r = n // val
        total += val * (r - l + 1)
        l = r + 1
    return total

def count_hash_segments(s):
    segments = []
    i = 0
    while i < len(s):
        if s[i] == '#':
            start = i
            while i < len(s) and s[i] == '#':
                i += 1
            segments.append((start, i - 1, i - start))  # start, end, length
        else:
            i += 1
    return segments

MOD = 998244353

def precompute_factorials(n):
    fact = [1] * (n + 1)
    inv = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i-1] * i % MOD

    inv[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n - 1, -1, -1):
        inv[i] = inv[i + 1] * (i + 1) % MOD

    return fact, inv

def solution(input_str):
    n, k, l = map(int, input_str.strip().split())

    fact, inv = precompute_factorials(n * 2 + 200)

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv[r] % MOD * inv[n - r] % MOD

    E = 0
    for j in range(k, n + 1):
        for m in range(n - j + 1):
            term = nCr(n, j) % MOD
            term = term * nCr(n - j, m) % MOD
            term = term * ((-1) if m % 2 == 1 else 1) % MOD
            term = term * pow(2, j + m, MOD) % MOD

            num = fact[j + m] % MOD
            num = num * fact[j + m] % MOD
            den = fact[2 * j + 2 * m + 1] % MOD

            term = term * num % MOD * pow(den, MOD - 2, MOD) % MOD
            term = term * l % MOD

            E = (E + term) % MOD

    if E < 0:
        E += MOD

    return str(E)

