def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    edge_list = []

    for i in range(1, k + 1):
        a, b = map(int, lines[i].split())
        edge_list.append((a, b))
        adj[a].append(b)
        adj[b].append(a)

    deg = [len(adj[i]) for i in range(n + 1)]
    avg_degree = sum(deg[1:]) / n

    keep = [0] * (n + 1)

    # Special case: all degrees equal
    if len(set(deg[1:])) == 1:
        if n == 2:
            # For n=2 with equal degrees, first member keeps
            keep[1] = 1
        # Else: no one keeps (as in triangle case)
    else:
        # Degrees differ - those above average keep
        for i in range(1, n + 1):
            if deg[i] > avg_degree:
                keep[i] = 1

    keepers = [i for i in range(1, n + 1) if keep[i]]

    result_lines = []
    result_lines.append(str(len(keepers)))
    result_lines.append(" ".join(map(str, keepers)) if keepers else "")

    for a, b in edge_list:
        if keep[a] == keep[b]:
            ret = 0
        else:
            ret = 1
        result_lines.append(str(a) + " " + str(b) + " " + str(ret))

    return "\n".join(result_lines)

def solution(input_str):
    lines = input_str.strip().split('\n')
    m = int(lines[0])

    results = []

    def is_valid_set(a_s, b_s, set_num):
        """Returns 1 if A wins, -1 if B wins, 0 if invalid"""
        if set_num < 5:
            min_pts = 25
            max_opp = 24
        else:
            min_pts = 15
            max_opp = 14

        # A wins
        if a_s >= min_pts and (b_s <= max_opp or a_s - b_s >= 2):
            return 1
        # B wins
        if b_s >= min_pts and (a_s <= max_opp or b_s - a_s >= 2):
            return -1
        return 0

    def find_best(a_total, b_total):
        """Find the best valid sequence of set scores"""
        best_seq = None

        def search(idx, cur_a, cur_b, wins_a, wins_b, seq):
            nonlocal best_seq

            if len(seq) == 5:
                if cur_a == a_total and cur_b == b_total and wins_a == 3:
                    best_seq = seq[:]
                    return True
                return False

            # Pruning: already won match or can't win match
            if wins_a >= 3:
                return False
            if wins_a + wins_b < 3 and 5 - idx < 3 - wins_a:
                return False

            # Higher set scores first to prefer deuce scenarios
            max_a = max(25, a_total)
            max_b = max(15, b_total)

            # Generate sets from highest to lowest scores first
            for a_s in range(int((a_total + max_a) / 2), max(0, a_total - 150) - 1, -1):
                for b_s in range(int((b_total + max_b) / 2), max(0, b_total - 150) - 1, -1):
                    res = is_valid_set(a_s, b_s, idx + 1)
                    if res == 0:
                        continue

                    new_wins_a = wins_a + (1 if res == 1 else 0)
                    new_wins_b = wins_b + (1 if res == -1 else 0)

                    if a_total - cur_a - a_s >= 0 and b_total - cur_b - b_s >= 0:
                        if search(idx + 1, cur_a + a_s, cur_b + b_s, new_wins_a, new_wins_b, seq + [(a_s, b_s)]):
                            return True

            return False

        search(0, 0, 0, 0, 0, [])

        if best_seq is None:
            return None, []

        # Calculate wins: A wins 3 sets when they win the match
        wins_a = sum(1 for a_s, b_s in best_seq if a_s > b_s and is_valid_set(a_s, b_s, len(best_seq)))
        wins_b = sum(1 for a_s, b_s in best_seq if b_s > a_s)

        return wins_a, ['{}:{}'.format(s[0], s[1]) for s in best_seq]

    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())

        wins_a, sets_str = find_best(a, b)

        if wins_a is None:
            results.append("Impossible")
        else:
            score_str = f"{wins_a}:{len(sets_str) - wins_a}"
            results.append(f"{score_str}\n{' '.join(sets_str)} \n")

    return ''.join(results)

def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    frogs = []  # list of [current_pos, jump_value, original_index]
    for i in range(1, n + 1):
        p, a = map(int, lines[i].split())
        frogs.append([p, a, i])

    # Track which cells have frogs
    board = {}
    for i, (p, a, idx) in enumerate(frogs):
        board[p] = board.get(p, [])
        board[p].append(idx)

    eliminated = set()

    # Simulate game
    # Continue until no changes occur in a full cycle
    changed = True
    while changed:
        changed = False
        # Process frogs in order of input
        for orig_idx in range(1, n + 1):
            if orig_idx in eliminated:
                continue

            # Find the frog with this original index
            for frog_idx, (p, a, idx) in enumerate(frogs):
                if idx == orig_idx:
                    # This frog's turn
                    if a <= 0:
                        continue

                    # Calculate destination
                    dest = (p + a - 1) % m + 1

                    # Check if any frogs are at destination
                    if dest in board:
                        frogs_at_dest = [f for f in board[dest] if f not in eliminated]
                        if frogs_at_dest:
                            # Knock out frogs at destination
                            for dead_frog_idx in frogs_at_dest:
                                removed = frog[dead_frog_idx]
                                p, a, _ = removed[1]
                                board[dest] = [f for f in board[dest] if f not in removed]
                                eliminated.add(frogs[removed])

def rev(n):
    return int(str(n)[::-1])

def solution(input_str):
    """
    Find minimum x * y such that at least w lucky tickets exist in [1,x] × [1,y].
    A ticket (a,b) is lucky if a * b = rev(a) * rev(b).
    """
    input_str = input_str.strip()
    if not input_str:
        return "-1"

    parts = input_str.split()
    if len(parts) < 3:
        return "-1"

    try:
        maxx, maxy, w = int(parts[0]), int(parts[1]), int(parts[2])
    except ValueError:
        return "-1"

    if w <= 0:
        return "1 1"

    # Grid where lucky[a][b] = 1 if (a, b) is lucky
    lucky = [[0] * (maxy + 1) for _ in range(maxx + 1)]

    for a in range(1, maxx + 1):
        for b in range(1, maxy + 1):
            if a * b == rev(a) * rev(b):
                lucky[a][b] = 1

    # Build 2D prefix sum array
    # count[x][y] = number of lucky tickets in range [1,x] × [1,y]
    prefix = [[0] * (maxy + 1) for _ in range(maxx + 1)]
    for i in range(1, maxx + 1):
        for j in range(1, maxy + 1):
            prefix[i][j] = lucky[i][j] + prefix[i-1][j] + prefix[i][j-1] - prefix[i-1][j-1]

    # Find minimum x * y where count >= w
    best_x, best_y, best_area = None, None, float('inf')

    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            count = prefix[x][y]
            if count >= w:
                area = x * y
                # Keep best with minimum area
                if area < best_area:
                    best_area = area
                    best_x, best_y = x, y

    if best_x is None:
        return "-1"
    return f"{best_x} {best_y}"

def solution(input_str):
    import sys
    sys.setrecursionlimit(10000)

    a, b, n = map(int, input_str.strip().split())

    def check_pow(x, y):
        """Check if x^y >= n without overflow"""
        if y == 0:
            return x >= n
        res = 1
        for i in range(y):
            res *= x
            if res >= n:
                return True
        return False

    memo = {}

    def can_win(a, b):
        """Returns True if current player wins from state (a, b), False if loses"""
        key = (a, b)
        if key in memo:
            return memo[key]

        # If already terminal (impossible to play, lost)
        if check_pow(a, b):
            memo[key] = False
            return False

        can_force_loss = False

        # Try adding a box
        if not check_pow(a + 1, b):
            if not can_win(a + 1, b):
                can_force_loss = True

        # Try adding an item
        if not can_force_loss and not check_pow(a, b + 1):
            if not can_win(a, b + 1):
                can_force_loss = True

        memo[key] = can_force_loss
        return can_force_loss

    stas_wins = can_win(a, b)
    return "Stas\n\n" if stas_wins else "Masha\n\n"

def solution(input_str):
    MOD = 10**9 + 7
    input_str = input_str.strip()
    pos = [0]

    def peek():
        return input_str[pos[0]] if pos[0] < len(input_str) else None

    def advance():
        nonlocal pos
        if pos[0] < len(input_str):
            c = input_str[pos[0]]
            pos[0] += 1
            return c
        return None

    def parse_number():
        nonlocal pos
        num_chars = []
        while pos[0] < len(input_str) and input_str[pos[0]] in '0123456789':
            num_chars.append(input_str[pos[0]])
            pos[0] += 1
        return int(''.join(num_chars)) if num_chars else 0

    def parse_term():
        nonlocal pos
        l = parse_number()

        if peek() == '-':
            advance()
            r = parse_number()
            return {'type': 'range', 'l': l, 'r': r}
        elif peek() == '(':
            advance()
            expr = parse_expression()
            advance()  # consume ')'
            return {'type': 'repeat', 'n': l, 'inner_expr': expr}
        return {'type': 'number', 'value': l}

    def parse_expression():
        nonlocal pos
        result = parse_term()
        result_val, result_digits = evaluate(result)

        while peek() == '+':
            advance()
            next_term = parse_term()
            next_val, next_digits = evaluate(next_term)
            result_val = (result_val * pow(10, next_digits, MOD) + next_val) % MOD
            result_digits += next_digits

        return result

    def evaluate(node):
        if node['type'] == 'number':
            return node['value'], 0

        if node['type'] == 'range':
            total_val = 0
            total_digits = 0
            l, r = node['l'], node['r']
            for num in range(l, r + 1):
                s = str(num)
                total_val = (total_val * pow(10, len(s), MOD) + int(s)) % MOD
                total_digits += len(s)
            return total_val, total_digits

        if node['type'] == 'repeat':
            n = node['n']
            inner_val, inner_digits = evaluate(node['inner_expr'])
            if n == 0:
                return 0, 0
            r10d = pow(10, inner_digits, MOD)
            denominator = (r10d - 1 + MOD) % MOD
            if denominator == 0:
                return (pow(r10d, n, MOD) - 1 + MOD) % MOD, inner_digits * n
            else:
                geometric = (pow(r10d, n, MOD) - 1 + MOD) * pow(denominator, MOD - 2, MOD) % MOD
                return (inner_val * geometric) % MOD, inner_digits * n

    expr = parse_expression()
    val, _ = evaluate(expr)
    return str(val % MOD)

def s_func(n):
    digits = str(n)
    sorted_str = ''.join(sorted(digits))
    return int(sorted_str)

def solution(X):
    X_int = int(X)
    total = 0
    for i in range(1, X_int + 1):
        total += s_func(i)
    return total
